[9575]={"Die Bollwerke schwächen","Tötet den Wachhabenden Gargolmar, Omor den Narbenlosen und Nazan, den Drachen. Bringt Gargolmars Hand, Omors Huf und Nazans Kopf zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel."},
[9587]={"Düstere Neuigkeiten","Bringt den unheilvollen Brief zu Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel."},
[9588]={"Düstere Neuigkeiten","Bringt den unheilvollen Brief zu Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel."},
[9589]={"Blut bedeutet Leben","Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Gunny in der Ehrenfeste auf der Höllenfeuerhalbinsel."},
[9590]={"Blut bedeutet Leben","Sammelt 10 Phiolen mit Höllenorcblut und bringt sie zu Zenturio Caza'rez in Thrallmar auf der Höllenfeuerhalbinsel."},
[9607]={"Im Herzen des Hasses","Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Truppenkommandant Danath Trollbann in der Ehrenfeste auf der Höllenfeuerhalbinsel."},
[9608]={"Im Herzen des Hasses","Untersucht das gesamte Areal des Blutkessels und meldet Euch anschließend bei Nazgrel in Thrallmar auf der Höllenfeuerhalbinsel."},
[9630]={"Medivhs Tagebuch","Erzmagier Alturus am Gebirgspass der Totenwinde möchte, dass Ihr nach Karazhan geht und mit Wravien sprecht."},
[9631]={"Hilfe unter Kollegen","Bringt das verkohlte Knochenfragment zu Kalynna Lathred in Area 52 im Nethersturm."},
[9637]={"Kalynnas Bitte","Kalynna Lathred möchte, dass Ihr den Dämmerfolianten vom Großhexenmeister Nethekurse in den Zerschmetterten Hallen der Höllenfeuerzitadelle und das Buch der vergessenen Namen von Dunkelwirker Syth in den Sethekkhallen in Auchindoun besorgt. Ihr müsst diese Quest auf dem Schwierigkeitsgrad 'Heroisch' abschließen."},
[9638]={"In guten Händen","Sprecht mit Gradav in der Bibliothek des Wächters in Karazhan."},
[9639]={"Kamsis","Sprecht mit Kamsis in der Bibliothek des Wächters in Karazhan."},
[9640]={"Arans Schemen","Beschafft Medivhs Tagebuch und kehrt zu Kamsis in der Bibliothek des Wächters in Karazhan zurück."},
[9644]={"Schrecken der Nacht","Geht zur Terrasse des Meisters in Karazhan und benutzt Kalynnas Urne, um den Schrecken der Nacht zu rufen. Entzieht dem Körper des Schreckens die schwache arkane Essenz und bringt sie zu Erzmagier Alturus."},
[9645]={"Die Terrasse des Meisters","Geht zur Terrasse des Meisters in Karazhan und lest Medivhs Tagebuch. Kehrt danach mit Medivhs Tagebuch zu Erzmagier Alturus zurück."},
[9680]={"Die Vergangenheit aufwühlen","Erzmagier Alturus möchte, dass Ihr zu den Bergen südlich von Karazhan im Gebirgspass der Totenwinde geht und ein verkohltes Knochenfragment besorgt."},
[9714]={"Bringt mir ein weiteres Gebüsch!","Wir können immer noch mehr Bluthibiskus von den Schlurfern, Sumpfriesen und Tiefenfledermäusen im Echsenkessel gebrauchen. Bringt sie mir in Bündeln zu je fünf, und ich werde Euch sehr dankbar sein."},
[9715]={"Bringt mir ein Gebüsch!","Sammelt 5 Stück Bluthibiskus und bringt sie zu Gzhun'tt in Sporeggar in den Zangarmarschen."},
[9717]={"Los geht's!","Besorgt einen Tiefensporenfarn und bringt ihn zu T'shu in Sporeggar in den Zangarmarschen."},
[9719]={"Tötet die Mutter","Bringt das Gehirn der Schattenmutter zu Khn'nix in Sporeggar in den Zangarmarschen."},
[9737]={"Wahre Meister des Lichts","Verwendet die Löschmischung in der Nähe der ewigen Flamme in der Alonsuskapelle, um den Schutz des Lichts zu brechen. Seid bereit, jeden zu töten, der versucht, die Kapelle zu verteidigen."},
[9738]={"Bei der Arbeit verschollen","Findet heraus, was mit Erdbinder Rayge, Naturalist Biss, Jäter Gründaum und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang im Echsenkessel in den Zangarmarschen zurück."},
[9739]={"Die Misere der Sporlinge","Fahssn im Pilzgeflecht möchte, dass Ihr 10 reife Sporenbeutel sammelt."},
[9743]={"Natürliche Feinde","Bringt 6 Sumpflordranken zu Fahssn im Pilzgeflecht in den Zangarmarschen."},
[9763]={"Das Versteck des Kriegsherren","Behüterin Jhang möchte, dass Ihr Kriegsherr Kalithresh im Echsenkessel findet und tötet."},
[9764]={"Befehle von Lady Vashj","Bringt die Befehle von Lady Vashj zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen."},
[9765]={"Kriegsvorbereitungen","Besorgt die Waffen des Echsenkessels von den Naga im Echsenkessel und kehrt dann zu Ysiel Windsänger in der Zuflucht des Cenarius in den Zangarmarschen zurück."},
[9766]={"Waffen des Echsenkessels","Wir werden den eigenen Stahl der Naga in Waffen gegen sie umschmieden. Bringt mir alle Waffen, die Ihr aus dem Echsenkessel besorgen könnt."},
[9824]={"Arkane Störungen","Benutzt den violetten Aufzeichnungskristall in der Nähe von unterirdischen Wasserquellen im Keller des Meisters und kehrt zu Erzmagier Alturus außerhalb von Karazhan zurück."},
[9825]={"Rastlose Aktivität","Bringt 10 geisterhafte Essenzen zu Erzmagier Alturus außerhalb von Karazhan."},
[9826]={"Dalarankontaktpersonen","Bringt Alturus' Bericht zu Erzmagier Cedric am Rande von Dalaran."},
[9829]={"Khadgar","Bringt Alturus' Bericht zu Khadgar in Shattrath in den Wäldern von Terokkar."},
[9831]={"Nach Karazhan","Khadgar möchte, dass Ihr das Schattenlabyrinth von Auchindoun betretet und das erste Schlüsselfragment aus einem versteckten arkanen Behälter besorgt."},
[9832]={"Das zweite und das dritte Fragment","Besorgt das zweite Schlüsselfragment aus einem arkanen Behälter im Echsenkessel und das dritte Schlüsselfragment aus einem arkanen Behälter in der Festung der Stürme. Kehrt dann zu Khadgar in Shattrath zurück."},
[9836]={"Die Berührung des Meisters","Geht in die Höhlen der Zeit und überzeugt Medivh davon, den wiederhergestellten Schlüssel des Lehrlings zu aktivieren."},
[9837]={"Rückkehr zu Khadgar","Kehrt zu Khadgar in Shattrath zurück und zeigt ihm den Schlüssel des Meisters."},
[9838]={"Das Violette Auge","Sprecht mit Erzmagier Alturus außerhalb von Karazhan."},
[9840]={"Einschätzung der Situation","Findet Koren in Karazhan."},
[9843]={"Keannas Aufzeichnungen","Durchsucht die Gästezimmer in Karazhan nach Keannas Aufzeichnungen und bringt sie zu Erzmagier Alturus außerhalb von Karazhan."},
[9844]={"Eine dämonische Präsenz","Erzmagier Alturus möchte, dass Ihr die dämonische Präsenz an der Turmspitze von Karazhan zerstört."},
[9860]={"Neue Anweisungen","Sprecht mit Erzmagier Cedric am Rande von Dalaran."},
[9868]={"Das Totem von Kar'dash","Begleitet den festgehaltenen Mag'har aus dem Sonnenwindposten hinaus. Sprecht mit Garrosh in Garadar, wenn Ihr erfolgreich wart."},
[9872]={"Eindringlinge der Finsterblut","Bringt die Invasionspläne der Finsterblut zu Garrosh."},
[9888]={"Der unfähige Anführer","Jorin Totauge möchte, dass Ihr Kilrath sucht und mit ihm sprecht."},
[9889]={"Nicht den Fetten töten!","Kilrath in den Wäldern von Terokkar möchte, dass Ihr 10 Eindringlinge der Felsfäuste tötet und Unkor den Rücksichtslosen so lange schlagt, bis er redet."},
[9890]={"Erfolg!","Teilt Kilrath in den Wäldern von Terokkar die Informationen, die Ihr aus dem Oger geprügelt habt, mit."},
[9891]={"Weil Kilrath ein Feigling ist","Erzählt Jorin Totauge in Garadar in Nagrand, was Ihr aus Unkor herausprügeln konntet."},
[9906]={"Sag's mit Fäusten","Jorin Totauge in Garadar in Nagrand möchte, dass Ihr 15 Zermalmer der Felsfäuste und 15 Mystiker der Felsfäuste tötet."},
[9907]={"Ein kühner Angriff","Jorin Totauge in Garadar in Nagrand möchte, dass Ihr 25 Krieger der Felsfäuste und 25 Magier der Felsfäuste tötet."},
[9919]={"Sporeggar","Geht nach Sporeggar, nördlich vom Pilzgeflecht, und bringt die geborgenen Sporensäcke zu Msshi'fn."},
[9927]={"Erbarmungslose Gerissenheit","Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr 20 Ogerbanner der Totschläger in die Körper von Bewohnern von Kil'sorge in der Festung Kil'sorge rammt. Bringt unbenutzte Ogerbanner der Totschläger zu ihm zurück."},
[9928]={"Waffen zur Täuschung","Lantresor von der Klinge in den Ruinen der Brennenden Klinge Nagrand möchte, dass Ihr 20 Waffen von Kil'sorge besorgt."},
[9931]={"Sich für den Gefallen revanchieren","Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr 20 Banner von Kil'sorge in die Leichen der Totschlägeroger in den Ruinen des Lachenden Schädels rammt. Bringt unbenutzte Banner von Kil'sorge zu ihm zurück."},
[9932]={"Beweismaterial","Lantresor von der Klinge in den Ruinen der Brennenden Klinge in Nagrand möchte, dass Ihr die feuchte Wolldecke am lodernden Scheiterhaufen der Totschläger im Hof des Lachenden Schädels benutzt, um Signale an seine Oger zu senden."},
[9934]={"Nachricht für Garadar","Bringt das Friedensangebot der Brennenden Klinge zu Garrosh in Garadar."},
[9982]={"Er nannte sich Altruis...","Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand."},
[9983]={"Er nannte sich Altruis...","Wenn Ihr die Brennende Legion bekämpfen wollt, sucht Altruis den Leider im Westen von Nagrand."},
[9991]={"Inspektion des Lagers","Lehnt Euch zurück und genießt Euren Flug. Sprecht mit Altruis wenn die Besichtigung abgeschlossen ist."},
[9999]={"Spiel auf Zeit","Altruis der Leider im westlichen Nagrand möchte, dass Ihr 2 Legionäre der Teufelswache, 3 Ingenieure der Mo'arg und 8 Tüftler der Gan'arg tötet."},
[10001]={"Der Meisterplaner","Altruis der Leider im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners besorgt."},
[10004]={"Geduld und Verständnis","Altruis der Leider im westlichen Nagrand möchte, dass Ihr die Blaupausen des Meisterplaners zu Sal'salabim in Shattrath bringt und ihn überredet, euch zu helfen."},
[10009]={"Ein paar Schädel spalten","Sal'salabim in Shattrath möchte, dass Ihr Raliqs Schulden, Kusch'kuschs Schulden und Floons Schulden eintreibt."},
[10010]={"So einfach ist das?","Sal'salabim in Shattrath möchte, dass Ihr zu Altruis dem Leider im westlichen Nagrand zurückkehrt."},
[10011]={"Konstruktionslager: zerstört","Altruis der Leider im westlichen Nagrand möchte, dass Ihr das Konstruktionslager: Hass und das Konstruktionslager: Furcht zerstört."},
[10044]={"Ein Besuch bei der Großmutter","Sprecht mit Großmutter Geyah und hört Euch an, was sie zu sagen hat."},
[10045]={"Zutaten sammeln","Großmutter Geyah in Garadar in Nagrand möchte, dass Ihr 1 Olembawurzel, 1 Marschenbeere, 1 Telaarifarn und 1 Drachenwirbel sammelt."},
[10081]={"Mutter Kashur treffen","Großmutter Geyah möchte, dass Ihr mit Mutter Kashur sprecht."},
[10082]={"Die aufgebrachten Ahnen","Mutter Kashur möchte, dass Ihr 15 aufgebrachte Orcgeister tötet."},
[10085]={"Ein Besuch bei den Ahnen","Mutter Kashur im Ahnengrund in Nagrand möchte, dass Ihr den Sonnenwindposten, die Ruinen des Lachenden Schädels, Garadar und die Ruinen des Blutenden Auges besucht."},
[10091]={"Seeleninstrumente","Stehlt 5 Seeleninstrumente und bringt sie zu Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath."},
[10094]={"Der Kodex des Blutes","Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun."},
[10095]={"In das Herz des Labyrinths","Vernichtet Murmur und informiert danach Spionagemeisterin Mehlisah Hochkrone auf der Terrasse des Lichts in Shattrath über die Geschehnisse im Schattenlabyrinth."},
[10097]={"Bruder gegen Bruder","Tötet Dunkelwirker Syth in den Sethekkhallen und befreit Lakka. Kehrt zu Isfar außerhalb der Sethekkhallen zurück, wenn Ihr die Aufgabe abgeschlossen habt."},
[10098]={"Terokks Erbe","Bringt Terokks Maske, Terokks Federkiel und die Sage von Terokk zu Isfar außerhalb der Sethekkhallen."},
[10101]={"Wenn Geister sprechen","Mutter Kashur im Ahnengrund in Nagrand bittet Euch, Eurer Vision auf den Grund zu gehen. Findet K'ure in Oshu'gun."},
[10102]={"Ein gelüftetes Geheimnis","Sprecht mit A'dal in Shattrath."},
[10107]={"Diplomatische Maßnahmen","Jorin Totauge in Garadar in Nagrand möchte, dass Ihr Lantresor von der Klinge in den Ruinen der Brennenden Klinge findet und mit ihm sprecht."},
[10120]={"Ankunft in der Scherbenwelt","Generalleutnant Orion beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Orions Bericht zu Vlagga Freyfeder bringt."},
[10121]={"Die Brennende Legion ausrotten","Sprecht mit Unteroffizier Schädelbrecher bei der Versorgungskarawane außerhalb von Thrallmar im Osten."},
[10123]={"Teufelsfunkenklamm","Unteroffizier Schädelbrecher bei der Versorgungskarawane östlich von Thrallmar auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet."},
[10124]={"Vorposten: Häschersturz","Meldet Euch bei Vorpostenkommandant To'arch im Häschersturz."},
[10141]={"Wiedergeburt der Brennenden Legion","Sprecht mit Unteroffizier Altumus bei der östlichen Versorgungskarawane außerhalb der Ehrenfeste im Osten."},
[10142]={"Der Pfad der Pein","Unteroffizier Altumus bei der östlichen Versorgungskarawane östlich der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet."},
[10143]={"Expeditionsposten","Meldet euch bei Vorpostenkommandant Wa'ppun im Expeditionsposten."},
[10164]={"Alles wird gut","Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr in die Auchenaikrypta geht und Exarch Maladaar vernichtet."},
[10165]={"Die Konkurrenz untergraben","Nexusprinz Haramad außerhalb der Managruft möchte, dass Ihr Nexusprinz Shaffar tötet und ihm Shaffars Bandagen bringt."},
[10167]={"Auchindoun...","Reist zur Auchenaikrypta in der Knochenwüste der Wälder von Terokkar und tötet Exarch Maladaar um den Geist von D'ore zu befreien."},
[10168]={"Was die Seele sieht","Sucht einen Seelenspiegel in der Auchenaikrypta und benutzt ihn, um einen getrübten Geist eines uralten Orcahnen von Nagrand zu rufen. Zerstört 15 getrübte Geister, damit die Ahnen in Frieden ruhen können. Kehrt zu Mutter Kashur im Ahnengrund zurück, wenn Ihr fertig seid."},
[10170]={"Rückkehr zur Großmutter","Kehrt nach Garadar zurück und sprecht mit Großmutter Geyah."},
[10171]={"Der untröstliche Häuptling","Großmutter Geyah in Garadar möchte, dass Ihr mit Garrosh sprecht."},
[10172]={"Es gibt keine Hoffnung","Sprecht mit Großmutter Geyah und erzählt ihr, was Garrosh Euch gesagt hat."},
[10173]={"Der Stab des Erzmagiers","Besorgt Erzmagier Vargoths Stab von Ekkorash der Inquisitorin und bringt ihn zu Ravandwyr in Area 52. Um Ekkorash aus ihrem Versteck hervorzulocken, streut das Beschwörungspulver auf die Kohlenpfanne in der Mitte der Ruinen."},
[10174]={"Der Fluch des violetten Turms","Benutzt Erzmagier Vargoths Stab um Kontakt mit Erzmagier Vargoth aufzunehmen. Falls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz."},
[10175]={"Thrall, Sohn Durotans","Reist nach Orgrimmar und überbringt Thrall Geyahs Nachricht."},
[10176]={"Ar'kelos der Wächter","Betretet den violetten Turm in der Mitte von Kirin'Var und besiegt Ar'kelos. Sprecht danach mit Erzmagier Vargoth."},
[10177]={"Ärger in Auchindoun","Meldet Euch bei Feldkommandeur Mahfuun beim Eingang zum Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar."},
[10178]={"Findet Spion To'gun","Findet Spion To'gun im Schattenlabyrinth von Auchindoun."},
[10188]={"Das Siegel von Krasus","Holt Euch das Siegel von Krasus von Zauberbinderin Maryana in der Manaschmiede Coruu, nordwestlich vom violetten Turm. Wenn Ihr das Siegel bekommen habt, benutzt Erzmagier Vargoths Stab, um ein Bild von ihm zu rufen und ihn über Eure Fortschritte zu informieren. Falls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz."},
[10192]={"Krasus' Kompendium","Holt Euch Krasus' Kompendium - Kapitel 1, Krasus' Kompendium - Kapitel 2 und Krasus' Kompendium - Kapitel 3 vom Ratsplatz von Kirin'Var. Benutzt Erzmagier Vargoths Stab um den Erzmagier zu kontaktieren, wenn Ihr die Kapitel zusammen habt. Falls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz."},
[10205]={"Sphärenräuber Nesaad","Tötet Sphärenräuber Nesaad und kehrt dann zu Netherpirscher Khay'ji in Area 52 im Nethersturm zurück."},
[10209]={"Beschwörer Kanthins Preis","Besiegt Beschwörer Kanthin in der Manaschmiede Duro auf der Insel nördlich des Sonnenzornpostens und holt den Stein von Gletscharius zurück. Wenn Ihr den Stein besorgt habt, benutzt Erzmagier Vargoths Stab, um den Erzmagier zu kontaktieren. Falls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz."},
[10212]={"Held der Mag'har","Kehrt zu Großmutter Geyah in Garadar in Nagrand zurück."},
[10216]={"Sicherheit geht vor","Konstrukteur Morphalius möchte, dass Ihr 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder tötet. Wenn Ihr damit fertig seid, sucht den astralen Transporter in der Kammer vor Shaffars Kammern und aktiviert ihn."},
[10218]={"Jemandes Arbeit zahlt sich aus","Begleitet Kryoingenieur Sha'heen sicher durch die Managruft, damit er die Astralmaterie aus Shaffars Astralsammlern entnehmen kann. Meldet Euch bei Nexusprinz Haramad außerhalb der Managruft beim Lager des Konsortiums, wenn Ihr erfolgreich wart."},
[10227]={"Ich sehe tote Draenei","Sprecht mit Ramdor dem Wahnsinnigen auf dem Knochenhaufen außerhalb der Auchenaikrypta."},
[10228]={"Ezekiel","Sprecht mit Ezekiel von Shattrath in Shattrath."},
[10231]={"Welches Buch? Ich sehe kein Buch.","Ezekiel sagt, dass das Buch gestohlen wurde. Eure einzige Spur führt Euch zu den Grobianen. Schaut nach, ob sie irgendwelche Informationen haben."},
[10251]={"Der große Plan des Meisters?","Sucht Nitrin den Gelehrten im verlassenen Rüstlager in Nagrand."},
[10252]={"Vision der Toten","Nitrin im verlassenen Rüstlager in Nagrand möchte, dass Ihr ihm 1 Augapfel eines Berggronns, 1 fehlerloser Schnabel eines großen Windrocs und 1 Tran eines gealterten Grollhufs bringt."},
[10253]={"Levixus der Seelenrufer","Vernichtet Levixus und nehmt Euch das Buch der Toten aus seinem Besitz. Bringt das Buch der Toten zu Ramdor dem Wahnsinnigen außerhalb der Auchenaikrypta am Eingang zu Auchindoun. Ihr hattet eine Vereinbarung, erinnert Ihr Euch?"},
[10256]={"Den Schlüsselmeister finden","Sucht Apex und besorgt Euch Apex' Kristallfokus. Kehrt dann zum violetten Turm zurück und benutzt Apex' Kristallfokus in der Nähe von Erzmagier Vargoths Kugel um herauszufinden, wer den Schlüssel zum Fluch des Turms hat."},
[10257]={"Den Schlüsselstein erobern","Reist zur Botanika der Festung der Stürme und besorgt Euch den Schlüsselstein von Kommandant Sarannis. Bringt ihn danach zu Erzmagier Vargoth im violetten Turm."},
[10262]={"Ein Hügel voll Astraler","Sammelt 10 Insignien der Zaxxis und kehrt dann zu Netherpirscher Khay'ji in Area 52 im Nethersturm zurück."},
[10265]={"Kristallsammlung des Konsortiums","Besorgt ein Kristallartefakt von Arklon und bringt es zu Netherpirscher Khay'ji in Area 52 im Nethersturm."},
[10266]={"Bitte um Unterstützung","Sucht Gahruj und bietet ihm Eure Hilfe an. Er befindet sich im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm."},
[10267]={"Rechtmäßiger Besitz","Sammelt 10 Kästen mit Vermessungsausrüstung und bringt sie zu Gahruj im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm."},
[10268]={"Eine Audienz beim Prinzen","Bringt die Vermessungsausrüstung zum Bild von Nexusprinz Haramad in der Sturmsäule im Nethersturm."},
[10269]={"Triangulationspunkt Eins","Benutzt das Triangulationsgerät, um den Weg zum ersten Triangulationspunkt zu bestimmen. Wenn Ihr in gefunden habt, meldet die Position an Händler Hazzin beim Wachposten des Protektorats auf der Insel der Manaschmiede Ultris im Nethersturm."},
[10275]={"Triangulationspunkt Zwei","Benutzt das Triangulationsgerät, um den Weg zum zweiten Triangulationspunkt zu bestimmen. Wenn Ihr in gefunden habt, meldet die Position an Windhändler Tuluman bei Tulumans Landeplatz auf der anderen Seite der Brücke zu der Insel der Manaschmiede Ara im Nethersturm."},
[10276]={"Das volle Dreieck","Besorgt Euch den Kristall von Ata'mal und bringt ihn zum Bild von Nexusprinz Haramad in der Sturmsäule im Nethersturm."},
[10277]={"Die Höhlen der Zeit","Andormu in den Höhlen der Zeit möchte, dass Ihr der Bewahrerin der Zeit durch die Höhle folgt."},
[10279]={"Zum Hort des Meisters","Sprecht mit Andormu in den Höhlen der Zeit."},
[10280]={"Sonderlieferung nach Shattrath","Bringt den Kristall von Ata'mal zu A'dal auf der Terrasse des Lichts in Shattrath."},
[10282]={"Das alte Hügelland","Andormu in den Höhlen der Zeit bittet Euch, ins Alte Hügelland zu reisen und mit Erozion zu sprechen."},
[10283]={"Tarethas Ablenkungsmanöver","Reist zur Burg Durnholde und platziert mit Hilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke. Sprecht mit Thrall im Kellergefängnis der Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt."},
[10284]={"Flucht aus Durnholde","Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen. Sprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt."},
[10285]={"Rückkehr zu Andormu","Kehrt zu dem jungen Andormu in den Höhlen der Zeit in Tanaris zurück."},
[10289]={"Reise nach Thrallmar","Nehmt Vlagga Freyfeders Windreiter nach Thrallmar. Bringt Orions Bericht zu General Krakork."},
[10291]={"Bericht an Nazgrel","General Krakork in Thrallmar möchte, dass Ihr mit Nazgrel sprecht."},
[10296]={"Der schwarze Morast","Reist durch die Höhlen der Zeit in den schwarzen Morast während der Öffnung des Dunklen Portals und sprecht mit Sa'at."},
[10297]={"Die Öffnung des Dunklen Portals","Sa'at im schwarzen Morast der Höhlen der Zeit möchte, dass Ihr Medivh verteidigt, bis er das Dunkle Portal geöffnet hat. Kehrt zu Sa'at zurück, wenn Ihr erfolgreich wart."},
[10298]={"Held des Schwarms","Kehrt zum Kind, Andormu, in den Höhlen der Zeit in Tanaris zurück."},
[10300]={"Den Stab wiederherstellen","Besorgt 4 fehlerlose Kristallsplitter von den Geistern in den Ruinen von Enkaat und bringt sie zu Ravandwyr in Area 52."},
[10301]={"Das Kompendium öffnen","Besorgt Euch das heliotrope Oculus von Zauberhäscherin Marathelle im Sonnenzornposten. Benutzt Erzmagier Vargoths Stab, um ihn zu kontaktieren, wenn Ihr fertig seid. Falls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz."},
[10445]={"Die Phiolen der Ewigkeit","Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole von Lady Vashj im Echsenkessel und die Überreste von Kaels Phiole von Kael'thas Sonnenwanderer in der Festung der Stürme besorgt."},
[10458]={"Wütende Geister des Feuers und der Erde","Erdheiler Torlok beim Altar der Verdammnis im Schattenmondtal möchte, dass Ihr das Totem der Geister benutzt, um 8 Erdenseelen und 8 Feuerseelen einzufangen."},
[10460]={"Das Versprechen des Verteidigers"},
[10461]={"Das Versprechen des Bewahrers"},
[10462]={"Das Versprechen des Helden","Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte. Dieser Ring wurde mit einem Tropfen aus dem Brunnen der Ewigkeit verstärkt. Wenn Ihr Euch den Wächtern der Sande gegenüber beweist, wird er an Macht gewinnen."},
[10463]={"Das Versprechen des Weisen","Seid Ihr sicher, dass Ihr diesen Pfad gehen wollt, <Name>? Das ist keine Entscheidung, die leichtfertig getroffen werden sollte. Dieser Ring wurde mit einem Tropfen aus dem Brunnen der Ewigkeit verstärkt. Wenn Ihr Euch den Wächtern der Sande gegenüber beweist, wird er an Macht gewinnen."},
[10464]={"Das Gelöbnis des Weisen","Bringt Euer Band der Ewigkeit zu Soridormi in den Höhlen der Zeit, wenn Ihr einen wohlwollenden Ruf bei den Wächtern der Sande erlangt habt."},
