[8151]={"El talismán del cazador","Habla con Ogtinc en Azshara."},
[8153]={"Cornamenta de trotador","Llévale una cornamenta perfecta de trotador a Ogtinc en Azshara. Ogtinc vive en lo alto del precipicio al noreste de las Ruinas de Eldarath."},
[8181]={"La confrontación con Yeh'kinya","Habla con Yeh'kinya."},
[8182]={"La mano de Rastakhan","Habla con Molthor en Tuercespina."},
[8183]={"El corazón de Hakkar","Lleva el corazón de Hakkar a Molthor en Isla Yojamba."},
