[8153]={"Galhada de ginete","Leve um par de Galhadas Perfeitas de Ginete para Ogtinc em Azshara. Ogtinc vive no alto dos penhascos a nordeste das Ruínas de Eldarath."},
[8181]={"Confronte Yeh'kinya","Fale com Yeh'kinya."},
[8182]={"A Mão de Rastakhan","Fale com Molthor na Selva do Espinhaço."},
[8183]={"O coração de Hakkar","Leve o Coração de Hakkar a Molthor na Ilha Yojamba."},
